import{_ as o,a0 as a,w as i,s as l,ao as r,I as e,a1 as u,A as s,x as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"如何在 Ubuntu 上设置多语言输入法 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 上设置多语言输入法 | LCTT (201908) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 上设置多语言输入法 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 上设置多语言输入法 | LCTT (201908) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201908/20190815 How To Setup Multilingual Input Method On Ubuntu","title":"如何在 Ubuntu 上设置多语言输入法","tag":"201908","desc":""},"relativePath":"201908/20190815 How To Setup Multilingual Input Method On Ubuntu.md","filePath":"[post].md"}'),g={name:"201908/20190815 How To Setup Multilingual Input Method On Ubuntu.md"};function m(b,t,d,h,w,c){const p=a("Link");return i(),l("div",null,[t[16]||(t[16]=r('<h1 id="如何在-ubuntu-上设置多语言输入法" tabindex="-1">如何在 Ubuntu 上设置多语言输入法 <a class="header-anchor" href="#如何在-ubuntu-上设置多语言输入法" aria-label="Permalink to “如何在 Ubuntu 上设置多语言输入法”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/201908/21/231916g3gxbhybq0zv0q1h.jpg" alt=""></p><p>或许你不知道，在印度有数以百计的语言被使用，其中 22 种被印度机构列为官方语言。我的母语不是英语，因此当我需要从英语输入或者翻译到我的母语泰米尔语时我经常使用<strong>谷歌翻译</strong>。嗯，我估计我不再需要依靠谷歌翻译了。我刚发现在 Ubuntu 上输入印度语的好办法。这篇教程解释了如何配置多语言输入法的方法。这个是为 Ubuntu 18.04 LTS 特别打造的，但是它可以在其它类 Ubuntu 系统例如 Linux mint、Elementary OS 上使用。</p><h3 id="在-ubuntu-linux-上设置多语言输入法" tabindex="-1">在 Ubuntu Linux 上设置多语言输入法 <a class="header-anchor" href="#在-ubuntu-linux-上设置多语言输入法" aria-label="Permalink to “在 Ubuntu Linux 上设置多语言输入法”">​</a></h3><p>通过 <strong>IBus</strong> 的帮助，我们可以轻松在 Ubuntu 及其衍生物上配置多语言输入法。Ibus，代表 <strong>I</strong> ntelligent <strong>I</strong> nput <strong>Bus</strong>（智能输入总线），是一种针对类 Unix 操作系统下多语言输入的输入法框架。它使得我们可以在大多数 GUI 应用例如 LibreOffice 下输入母语。</p><h3 id="在-ubuntu-上安装-ibus" tabindex="-1">在 Ubuntu 上安装 IBus <a class="header-anchor" href="#在-ubuntu-上安装-ibus" aria-label="Permalink to “在 Ubuntu 上安装 IBus”">​</a></h3><p>在 Ubuntu 上 安装 IBus 包，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install ibus-m17n</span></span></code></pre></div><p>Ibus-m17n 包提供了许多印度语和其它国家语言包括阿姆哈拉语，阿拉伯语，阿美尼亚语，阿萨姆语，阿萨巴斯卡语，白俄罗斯语，孟加拉语，缅甸语，中高棉语，占文，<strong>汉语</strong>，克里语，克罗地亚语，捷克语，丹麦语，迪维希语，马尔代夫语，世界语，法语，格鲁吉亚语，古/现代希腊语，古吉拉特语，希伯来语，因纽特语，日语，卡纳达语，克什米尔语，哈萨克语，韩语，老挝语，马来语，马拉地语，尼泊尔语，欧吉布威语，欧瑞亚语，旁遮普语，波斯语，普什图语，俄语，梵语，塞尔维亚语，四川彝文，彝文，西格西卡语，信德语，僧伽罗语，斯洛伐克语，瑞典语，泰语，泰米尔语，泰卢固语，藏语，维吾尔语，乌都语，乌兹别克语，越语及意第绪语。</p><h5 id="添加输入语言" tabindex="-1">添加输入语言 <a class="header-anchor" href="#添加输入语言" aria-label="Permalink to “添加输入语言”">​</a></h5><p>我们可以在系统里的<strong>设置</strong>部分添加语言。点击你的 Ubuntu 桌面右上角的下拉箭头选择底部左下角的设置图标。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/07/Ubuntu-system-settings.png" alt=""></p><p><em>从顶部面板启动系统设置</em></p><p>从设置部分，点击左侧面板的<strong>区域及语言</strong>选项。再点击右侧<strong>输入来源</strong>标签下的<strong>+</strong>（加号）按钮。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/08/Region-language-in-Settings-ubuntu.png" alt=""></p><p><em>设置部分的区域及语言选项</em></p><p>在下个窗口，点击<strong>三个垂直的点</strong>按钮。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/08/Add-input-source-in-Ubuntu.png" alt=""></p><p><em>在 Ubuntu 里添加输入来源</em></p><p>搜寻并选择你想从列表中添加的输入语言。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/08/Add-input-language.png" alt=""></p><p><em>添加输入语言</em></p><p>在本篇教程中，我将加入<strong>泰米尔</strong>语。在选择语言后，点击<strong>添加</strong>按钮。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/08/Add-Input-Source-Ubuntu.png" alt=""></p><p><em>添加输入来源</em></p><p>现在你会看到选中的输入来源已经被添加了。你会在输入来源标签下的区域及语言选项中看到它。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/08/Input-sources-Ubuntu.png" alt=""></p><p><em>Ubuntu 里的输入来源选项</em></p><p>点击输入来源标签下的“管理安装的语言”按钮</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/08/Manage-Installed-Languages.png" alt=""></p><p><em>在 Ubuntu 里管理安装的语言</em></p><p>接下来你会被询问是否想要为选定语言安装翻译包。如果你想的话你可以安装它们。或者仅仅选择“稍后提醒我”按钮。你下次打开的时候会收到统治。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/08/The-language-support-is-not-installed-completely.png" alt=""></p><p><em>语言支持没完全安装好</em></p><p>一旦翻译包安装好，点击<strong>安装/移除语言</strong>按钮。同时确保 IBus 在键盘输入法系统中被选中。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/08/Install-Remove-languages.png" alt=""></p><p><em>在 Ubuntu 中安装/移除语言</em></p><p>从列表中选择你想要的语言并点击采用按钮。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/08/Choose-language.png" alt=""></p><p><em>选择输入语言</em></p><p>到此为止了。我们已成功在 Ubuntu 18.04 桌面上配置好多语输入方法。同样的，你可以添加尽可能多的输入语言。</p><p>在添加完所有语言来源后，登出再登陆回去。</p><h3 id="用印度语或者你喜欢的语言输入" tabindex="-1">用印度语或者你喜欢的语言输入 <a class="header-anchor" href="#用印度语或者你喜欢的语言输入" aria-label="Permalink to “用印度语或者你喜欢的语言输入”">​</a></h3><p>一旦你添加完所有语言后，你就会从你的 Ubuntu 桌面上的顶端菜单下载栏看到它们。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/08/Choose-input-language-from-top-bar-in-Ubuntu.png" alt=""></p><p><em>从 Ubuntu 桌面的顶端栏选择输入语言。</em></p><p>你也可以使用键盘上的<strong>徽标键+空格键</strong>在不同语言中切换。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/08/Choose-input-language-using-SuperSpace-keys.png" alt=""></p><p><em>在 Ubuntu 里用<strong>徽标键+空格键</strong>选择输入语言</em></p><p>打开任何 GUI 文本编辑器/应用开始打字吧！</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/08/Setup-Multilingual-Input-Method-On-Ubuntu.png" alt=""></p><p><em>在 Ubuntu 中用印度语输入</em></p><h3 id="将-ibus-加入启动应用" tabindex="-1">将 IBus 加入启动应用 <a class="header-anchor" href="#将-ibus-加入启动应用" aria-label="Permalink to “将 IBus 加入启动应用”">​</a></h3><p>我们需要让 IBus 在每次重启后自动打开，这样每次你想要用自己喜欢的语言输入的时候就无须手动打开。</p><p>为此仅须在面板中输入“开机应用”点开开机应用选项。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/08/Launch-startup-applications-in-ubuntu.png" alt=""></p><p>在下个窗口，点击添加，在名字栏输入“Ibus”并在命令栏输入“ibus-daemon”点击添加按钮。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/08/Add-Ibus-to-startup-applications-on-Ubuntu.png" alt=""></p><p><em>在 Ubuntu 中将 Ibus 添加进开机启动项</em></p><p>从现在起 IBus 将在系统启动后自动开始。</p><p>现在到你的回合了。在什么应用/工具中你用当地的印度语输入？在下方评论区让我们知道它们。</p><p>参考：</p>',62)),e("ul",null,[e("li",null,[u(p,{href:"https://help.ubuntu.com/community/ibus"},{default:s(()=>[...t[0]||(t[0]=[n("IBus – Ubuntu 社区百科",-1)])]),_:1})])]),t[17]||(t[17]=e("hr",null,null,-1)),e("p",null,[t[2]||(t[2]=n("via: ",-1)),u(p,{href:"https://www.ostechnix.com/how-to-setup-multilingual-input-method-on-ubuntu/"},{default:s(()=>[...t[1]||(t[1]=[n("https://www.ostechnix.com/how-to-setup-multilingual-input-method-on-ubuntu/",-1)])]),_:1})]),e("p",null,[t[7]||(t[7]=n("作者：",-1)),u(p,{href:"https://www.ostechnix.com/author/sk/"},{default:s(()=>[...t[3]||(t[3]=[n("sk",-1)])]),_:1}),t[8]||(t[8]=n(" 选题：",-1)),u(p,{href:"https://github.com/lujun9972"},{default:s(()=>[...t[4]||(t[4]=[n("lujun9972",-1)])]),_:1}),t[9]||(t[9]=n(" 译者：",-1)),u(p,{href:"https://github.com/tomjlw"},{default:s(()=>[...t[5]||(t[5]=[n("tomjlw",-1)])]),_:1}),t[10]||(t[10]=n(" 校对：",-1)),u(p,{href:"https://github.com/wxy"},{default:s(()=>[...t[6]||(t[6]=[n("wxy",-1)])]),_:1})]),e("p",null,[t[13]||(t[13]=n("本文由 ",-1)),u(p,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[11]||(t[11]=[n("LCTT",-1)])]),_:1}),t[14]||(t[14]=n(" 原创编译，",-1)),u(p,{href:"https://linux.cn/"},{default:s(()=>[...t[12]||(t[12]=[n("Linux中国",-1)])]),_:1}),t[15]||(t[15]=n(" 荣誉推出",-1))])])}const I=o(g,[["render",m]]);export{f as __pageData,I as default};
